import React, { useState, useEffect, useMemo } from "react";
import { attendanceAPI } from "../api_service";

const COLORS = {
  primary: "#4F46E5",
  primaryLight: "#EEF2FF",
  success: "#10B981",
  successLight: "#DCFCE7",
  danger: "#EF4444",
  dangerLight: "#FEE2E2",
  warning: "#F59E0B",
  warningLight: "#FEF3C7",
  textMain: "#1E293B",
  textMuted: "#64748B",
  border: "#E2E8F0",
  background: "#F8FAFC",
  surface: "#FFFFFF"
};

const Dashboard = ({ addNotification }) => {
  const [stats, setStats] = useState({
    active_students: 0,
    present_today: 0,
    absent_today: 0,
    summary: {
      unique_students: 0,
      total_records: 0,
      avg_confidence: 0,
      max_confidence: 0,
      min_confidence: 0
    }
  });

  const [attendanceLog, setAttendanceLog] = useState([]);
  const [statusList, setStatusList] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [autoRefresh, setAutoRefresh] = useState(false);
  const [lastUpdated, setLastUpdated] = useState(new Date());

  const loadData = async () => {
    try {
      if (attendanceLog.length === 0) setLoading(true);

      const [statsRes, logRes, statusRes] = await Promise.all([
        attendanceAPI.getStats(),
        attendanceAPI.getTodayLog(),
        attendanceAPI.getStatus()
      ]);

      const dataStats = statsRes?.data || {};
      const summary = dataStats.summary || {};

      setStats({
        active_students: Number(dataStats.active_students) || 0,
        present_today: Number(dataStats.present_today) || 0,
        absent_today: Number(dataStats.absent_today) || 0,
        summary: {
          unique_students: Number(summary.unique_students) || 0,
          total_records: Number(summary.total_records) || 0,
          avg_confidence: Number(summary.avg_confidence) || 0,
          max_confidence: Number(summary.max_confidence) || 0,
          min_confidence: Number(summary.min_confidence) || 0
        }
      });

      setAttendanceLog(Array.isArray(logRes?.data?.records) ? logRes.data.records : []);
      setStatusList(Array.isArray(statusRes?.data?.students) ? statusRes.data.students : []);
      setLastUpdated(new Date());
      setError(null);

    } catch (err) {
      console.error("❌ Erreur Dashboard API:", err);
      setError("Erreur de liaison avec le serveur. Vérifiez que le backend est lancé.");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadData();
  }, []);

  useEffect(() => {
    let timer;
    if (autoRefresh) {
      timer = setInterval(loadData, 10000);
    }
    return () => clearInterval(timer);
  }, [autoRefresh]);

  const statCards = useMemo(() => {
    const total = stats.active_students || 0;
    const present = stats.present_today || 0;
    const rate = total > 0 ? Math.round((present / total) * 100) : 0;

    return [
      { id: 'total', label: "Étudiants Inscrits", value: total, icon: "👥", color: COLORS.primary, bgColor: COLORS.primaryLight },
      { id: 'present', label: "Présents (Aujourd'hui)", value: present, icon: "✅", color: COLORS.success, bgColor: COLORS.successLight },
      { id: 'absent', label: "Absents", value: stats.absent_today, icon: "❌", color: COLORS.danger, bgColor: COLORS.dangerLight },
      { id: 'rate', label: "Taux de Présence", value: `${rate}%`, icon: "📈", color: "#8B5CF6", bgColor: "#F5F3FF" }
    ];
  }, [stats]);

  if (loading) {
    return (
      <div style={styles.loaderContainer}>
        <div style={styles.spinner}></div>
        <p style={styles.loaderText}>Chargement des données biométriques...</p>
      </div>
    );
  }

  return (
    <div style={styles.pageWrapper}>
      <header style={styles.header}>
        <div>
          <h1 style={styles.title}>Dashboard de Présence</h1>
          <p style={styles.subtitle}>Dernière mise à jour : {lastUpdated.toLocaleTimeString()}</p>
        </div>

        <div style={styles.actions}>
          <label style={styles.switchContainer}>
            <input 
              type="checkbox" 
              checked={autoRefresh} 
              onChange={() => setAutoRefresh(!autoRefresh)}
              style={styles.switchInput}
            />
            <span style={styles.switchLabel}>Auto-Refresh (10s)</span>
          </label>
          <button onClick={loadData} style={styles.refreshBtn}>
            🔄 Actualiser
          </button>
        </div>
      </header>

      {error && (
        <div style={styles.errorAlert}>
          <span style={{marginRight: 10}}>⚠️</span> {String(error)}
        </div>
      )}

      <div style={styles.statsGrid}>
        {statCards.map((card) => (
          <div key={card.id} style={styles.statCard}>
            <div style={{...styles.iconWrapper, backgroundColor: card.bgColor, color: card.color}}>
              {card.icon}
            </div>
            <div style={styles.statInfo}>
              <span style={styles.statLabel}>{card.label}</span>
              <span style={styles.statValue}>{card.value}</span>
            </div>
          </div>
        ))}
      </div>

      <div style={styles.mainLayout}>
        <section style={styles.sectionCard}>
          <div style={styles.sectionHeader}>
            <h3 style={styles.sectionTitle}>Journal des Entrées</h3>
            <span style={styles.badgeCount}>{attendanceLog.length} scans aujourd'hui</span>
          </div>

          <div style={styles.tableResponsive}>
            <table style={styles.table}>
              <thead>
                <tr>
                  <th style={styles.th}>Étudiant</th>
                  <th style={styles.th}>Heure de passage</th>
                  <th style={styles.th}>Confiance IA</th>
                </tr>
              </thead>
              <tbody>
                {attendanceLog.length > 0 ? (
                  attendanceLog.map((row, idx) => {
                    if (!row || typeof row !== 'object') return null;
                    return (
                      <tr key={idx} style={styles.tr}>
                        <td style={styles.tdBold}>
                          {String(row.student || row.name || row.full_name || 'Inconnu')}
                        </td>
                        <td style={styles.td}>
                          {String(row.timestamp || '—')}
                        </td>
                        <td style={styles.td}>
                          <div style={{
                            ...styles.confidenceBadge,
                            backgroundColor: (row.confidence || 0) > 0.8 ? COLORS.successLight : COLORS.warningLight,
                            color: (row.confidence || 0) > 0.8 ? COLORS.success : COLORS.warning
                          }}>
                            {((row.confidence || 0) * 100).toFixed(1)}%
                          </div>
                        </td>
                      </tr>
                    );
                  })
                ) : (
                  <tr>
                    <td colSpan="3" style={styles.emptyCell}>Aucune activité détectée pour le moment.</td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        </section>

        <div style={styles.rightColumn}>
          <section style={styles.sectionCard}>
            <h3 style={styles.sectionTitle}>Analyse de Précision</h3>
            <div style={styles.analyticsGrid}>
              <div style={styles.analyticRow}>
                <span style={styles.analyticLabel}>Confiance Max</span>
                <span style={{...styles.analyticValue, color: COLORS.success}}>
                  {(stats.summary.max_confidence * 100).toFixed(1)}%
                </span>
              </div>
              <div style={styles.analyticRow}>
                <span style={styles.analyticLabel}>Confiance Moyenne</span>
                <span style={{...styles.analyticValue, color: COLORS.primary}}>
                  {(stats.summary.avg_confidence * 100).toFixed(1)}%
                </span>
              </div>
              <div style={styles.analyticRow}>
                <span style={styles.analyticLabel}>Confiance Min</span>
                <span style={{...styles.analyticValue, color: COLORS.danger}}>
                  {(stats.summary.min_confidence * 100).toFixed(1)}%
                </span>
              </div>
              <div style={styles.divider}></div>
              <div style={styles.analyticRow}>
                <span style={styles.analyticLabel}>Total des scans</span>
                <span style={styles.analyticValue}>{stats.summary.total_records}</span>
              </div>
            </div>
          </section>

          <section style={{...styles.sectionCard, marginTop: 20}}>
            <h3 style={styles.sectionTitle}>Légende</h3>
            <div style={styles.legendItem}>
              <div style={{...styles.dot, backgroundColor: COLORS.success}}></div>
              <span>Présent : Détecté par caméra</span>
            </div>
            <div style={styles.legendItem}>
              <div style={{...styles.dot, backgroundColor: COLORS.danger}}></div>
              <span>Absent : Non encore vu</span>
            </div>
          </section>
        </div>
      </div>

      <section style={{...styles.sectionCard, marginTop: 25}}>
        <h3 style={styles.sectionTitle}>Statut Général de la Classe</h3>
        <div style={styles.tableResponsive}>
          <table style={styles.table}>
            <thead>
              <tr>
                <th style={styles.th}>Étudiant</th>
                <th style={styles.th}>Email</th>
                <th style={styles.th}>Statut Actuel</th>
              </tr>
            </thead>
            <tbody>
              {Array.isArray(statusList) && statusList.length > 0 ? (
                statusList.map((student, index) => {
                  if (!student || typeof student !== 'object') return null;
                  return (
                    <tr key={index} style={styles.tr}>
                      <td style={styles.tdBold}>
                        {String(student.name || student.full_name || 'Inconnu')}
                      </td>
                      <td style={styles.tdMuted}>
                        {String(student.email || '—')}
                      </td>
                      <td style={styles.td}>
                        <span style={{
                          ...styles.statusBadge,
                          backgroundColor: student.present ? COLORS.successLight : COLORS.dangerLight,
                          color: student.present ? COLORS.success : COLORS.danger
                        }}>
                          {student.present ? "Présent" : "Absent"}
                        </span>
                      </td>
                    </tr>
                  );
                })
              ) : (
                <tr>
                  <td colSpan="3" style={styles.emptyCell}>Aucun statut disponible.</td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </section>
    </div>
  );
};

const styles = {
  pageWrapper: { padding: "40px", backgroundColor: COLORS.background, minHeight: "100vh", fontFamily: "'Inter', sans-serif" },
  header: { display: "flex", justifyContent: "space-between", alignItems: "flex-start", marginBottom: "35px" },
  title: { fontSize: "28px", fontWeight: "800", color: COLORS.textMain, margin: 0 },
  subtitle: { fontSize: "14px", color: COLORS.textMuted, marginTop: "5px" },
  actions: { display: "flex", alignItems: "center", gap: "20px" },
  refreshBtn: { padding: "10px 20px", backgroundColor: COLORS.primary, color: "white", border: "none", borderRadius: "10px", fontWeight: "600", cursor: "pointer" },
  switchContainer: { display: "flex", alignItems: "center", gap: "8px", cursor: "pointer" },
  switchLabel: { fontSize: "13px", fontWeight: "500", color: COLORS.textMuted },
  errorAlert: { padding: "15px 20px", backgroundColor: COLORS.dangerLight, color: COLORS.danger, borderRadius: "12px", marginBottom: "25px", fontWeight: "500", border: `1px solid ${COLORS.danger}` },
  statsGrid: { display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(260px, 1fr))", gap: "25px", marginBottom: "35px" },
  statCard: { backgroundColor: COLORS.surface, padding: "25px", borderRadius: "20px", display: "flex", alignItems: "center", gap: "20px", boxShadow: "0 2px 10px rgba(0,0,0,0.03)", border: `1px solid ${COLORS.border}` },
  iconWrapper: { width: "60px", height: "60px", borderRadius: "15px", display: "flex", alignItems: "center", justifyContent: "center", fontSize: "24px" },
  statInfo: { display: "flex", flexDirection: "column" },
  statLabel: { fontSize: "14px", color: COLORS.textMuted, fontWeight: "500" },
  statValue: { fontSize: "24px", fontWeight: "800", color: COLORS.textMain },
  mainLayout: { display: "grid", gridTemplateColumns: "2fr 1fr", gap: "30px", alignItems: "start" },
  sectionCard: { backgroundColor: COLORS.surface, borderRadius: "20px", padding: "30px", border: `1px solid ${COLORS.border}`, boxShadow: "0 2px 10px rgba(0,0,0,0.03)" },
  sectionHeader: { display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "20px" },
  sectionTitle: { fontSize: "18px", fontWeight: "700", color: COLORS.textMain, margin: 0 },
  badgeCount: { fontSize: "12px", padding: "4px 12px", backgroundColor: COLORS.primaryLight, color: COLORS.primary, borderRadius: "20px", fontWeight: "600" },
