  tr: { borderBottom: `1px solid ${COLORS.background}`, transition: "background 0.2s" },
  td: { padding: "18px 10px", fontSize: "15px", color: COLORS.textMain },
  tdBold: { padding: "18px 10px", fontSize: "15px", fontWeight: "600", color: COLORS.textMain },
  tdMuted: { padding: "18px 10px", fontSize: "14px", color: COLORS.textMuted },
  confidenceBadge: { display: "inline-block", padding: "4px 10px", borderRadius: "8px", fontSize: "12px", fontWeight: "700" },
  statusBadge: { display: "inline-block", padding: "6px 14px", borderRadius: "10px", fontSize: "13px", fontWeight: "600" },
  analyticsGrid: { display: "flex", flexDirection: "column", gap: "18px" },
  analyticRow: { display: "flex", justifyContent: "space-between", alignItems: "center" },
  analyticLabel: { fontSize: "14px", color: COLORS.textMuted },
  analyticValue: { fontSize: "16px", fontWeight: "700" },
  divider: { height: "1px", backgroundColor: COLORS.border, margin: "10px 0" },
  legendItem: { display: "flex", alignItems: "center", gap: "12px", marginBottom: "12px", fontSize: "14px", color: COLORS.textMuted },
  dot: { width: "10px", height: "10px", borderRadius: "50%" },
  loaderContainer: { height: "100vh", display: "flex", flexDirection: "column", justifyContent: "center", alignItems: "center", backgroundColor: COLORS.background },
  spinner: { width: "50px", height: "50px", border: `5px solid ${COLORS.primaryLight}`, borderTop: `5px solid ${COLORS.primary}`, borderRadius: "50%", animation: "spin 1s linear infinite" },
  loaderText: { marginTop: "20px", color: COLORS.textMuted, fontWeight: "500" },
  emptyCell: { textAlign: "center", padding: "40px", color: COLORS.textMuted, fontSize: "14px", fontStyle: "italic" }
};

export default Dashboard;
